        minus=[];plus=[]
        while i<len(L) and not L[i].startswith('@@'):
            if L[i].startswith('-') and not L[i].startswith('---'):minus.append(L[i][1:])
            elif L[i].startswith('+') and not L[i].startswith('+++'):plus.append(L[i][1:])
            i+=1
