                if op!='equal':
                    print(' [%s] -%r\n      +%r'%(op,''.join(ta[max(0,a1-6):a1])[-60:]+'<<'+''.join(ta[a1:a2])+'>>','<<'+''.join(tb[b1:b2])+'>>'))
        for x in minus[len(plus):]:print(' ONLY-', x[:300])
        for x in plus[len(minus):]:print(' ONLY+', x[:600])
    else:i+=1
EOF

